 public:
  int kthSmallestSubarraySum(vector<int>& nums, int k) {
    int l = 0;
    int r = accumulate(nums.begin(), nums.end(), 0);

    while (l < r) {
      const int m = (l + r) / 2;
      if (numSubarrayLessThan(nums, m) >= k)
        r = m;
      else
        l = m + 1;
    }

    return l;
  }

 private:
